# This code has been fully generated by an AI.
"""Netzwerkadapter auflisten, auswählen und merken, damit der Server nur in einem Netz erreichbar ist."""

import ipaddress
import json
import logging
import socket
import sys
import threading
import time
from dataclasses import dataclass
from pathlib import Path

import psutil

log = logging.getLogger(__name__)

# So lange wartet der Start auf eine andere Wahl, bevor er den gemerkten Adapter nimmt.
WAIT_S = 10


@dataclass(frozen=True)
class Adapter:
    name: str
    ip: str | None
    netmask: str | None
    up: bool

    @property
    def usable(self) -> bool:
        return self.up and self.ip is not None

    @property
    def subnet(self) -> ipaddress.IPv4Network | None:
        if self.ip is None:
            return None
        return ipaddress.ip_network(f"{self.ip}/{self.netmask or '255.255.255.255'}", strict=False)


def adapters() -> list[Adapter]:
    """Alle Adapter außer Loopback; verbundene zuerst, der mit der Standardroute ganz oben."""
    stats, addrs = psutil.net_if_stats(), psutil.net_if_addrs()
    found = []
    for name in set(stats) | set(addrs):
        v4 = next((a for a in addrs.get(name, []) if a.family == socket.AF_INET), None)
        if v4 is not None and v4.address.startswith("127."):
            continue
        state = stats.get(name)
        found.append(Adapter(name, v4.address if v4 else None, v4.netmask if v4 else None,
                             bool(state and state.isup)))
    primary = _primary_ip()
    return sorted(found, key=lambda a: (not a.usable, a.ip != primary, a.name.lower()))


def own_addresses() -> set[str]:
    return {a.address for infos in psutil.net_if_addrs().values() for a in infos
            if a.family == socket.AF_INET}


def remembered(items: list[Adapter], saved: dict) -> Adapter | None:
    usable = [a for a in items if a.usable]
    # Erst über den Namen: per DHCP bekommt derselbe Adapter oft eine neue IP.
    return (next((a for a in usable if a.name == saved.get("name")), None)
            or next((a for a in usable if saved.get("ip") and a.ip == saved.get("ip")), None))


def choose(path: Path) -> Adapter | None:
    """Fragt in der Konsole nach dem Adapter; None, wenn keiner verbunden ist."""
    saved = _load(path)
    interactive = sys.stdin is not None and sys.stdin.isatty()
    while True:
        items = adapters()
        usable = [a for a in items if a.usable]
        last = remembered(items, saved)
        if saved and last is None:
            print(f"  Zuletzt gewählter Adapter „{saved.get('name')}“ ({saved.get('ip')}) ist gerade "
                  "nicht verbunden.")
        if not usable:
            return None
        default = last or usable[0]
        if len(usable) == 1 or not interactive:
            _save(path, default)
            return default
        _print_list(items, usable, last)
        number = usable.index(default) + 1
        if last is not None:
            prompt = (f"  Enter = [{number}] {default.name}, andere Nummer zum Wechseln, r = neu laden "
                      f"(weiter in {WAIT_S} s): ")
            answer = _ask(prompt, WAIT_S)
        else:
            answer = _ask(f"  Nummer wählen [Enter = {number}], r = neu laden: ", 0)
        answer = answer.strip().lower()
        if answer == "r":
            continue
        if not answer:
            picked = default
        elif answer.isdigit() and 1 <= int(answer) <= len(usable):
            picked = usable[int(answer) - 1]
        else:
            print(f"  Bitte eine Nummer von 1 bis {len(usable)} eingeben.")
            continue
        _save(path, picked)
        return picked


def watch(adapter: Adapter, stop: threading.Event) -> None:
    """Meldet in der Konsole, wenn der gewählte Adapter wegfällt oder wiederkommt."""
    alive = True
    while not stop.wait(5):
        current = next((a for a in adapters() if a.name == adapter.name), None)
        now = current is not None and current.usable and current.ip == adapter.ip
        if now == alive:
            continue
        alive = now
        if now:
            log.info("Netzwerkadapter „%s“ ist wieder verbunden (%s).", adapter.name, adapter.ip)
        else:
            log.warning("Netzwerkadapter „%s“ getrennt oder neue IP – Clients erreichen den Server nicht. "
                        "Adapter wieder verbinden oder Server neu starten.", adapter.name)


def _print_list(items: list[Adapter], usable: list[Adapter], last: Adapter | None) -> None:
    print(" Netzwerkadapter:")
    for a in items:
        mark = f"[{usable.index(a) + 1}]" if a in usable else " – "
        if a.usable:
            status = "verbunden"
        elif a.up:
            status = "ohne IPv4-Adresse"
        else:
            status = "nicht verbunden"
        hint = "  <- zuletzt gewählt" if a == last else ""
        print(f"   {mark:>4} {a.name[:30]:<30} {a.ip or '–':<16} {status}{hint}")


def _ask(prompt: str, timeout: float) -> str:
    print(prompt, end="", flush=True)
    if timeout and sys.platform == "win32":
        import msvcrt

        end = time.monotonic() + timeout
        while time.monotonic() < end:
            # Sobald jemand tippt, wartet die Eingabe ohne Zeitlimit.
            if msvcrt.kbhit():
                break
            time.sleep(0.05)
        else:
            print()
            return ""
    try:
        return input()
    except EOFError:
        return ""


def _primary_ip() -> str | None:
    try:
        # Verbindet nur logisch, sendet nichts; liefert die Adresse der Standardroute, auch ohne Internet.
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.connect(("10.255.255.255", 1))
            return s.getsockname()[0]
    except OSError:
        return None


def _load(path: Path) -> dict:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def _save(path: Path, adapter: Adapter) -> None:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps({"name": adapter.name, "ip": adapter.ip}), encoding="utf-8")
    except OSError as exc:
        log.warning("Gewählten Adapter nicht gespeichert: %s", exc)
